CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, status ENUM('ACTIVE','SUSPENDED','PENDING') NOT NULL DEFAULT 'PENDING', email_verified_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_users_status(status));
CREATE TABLE IF NOT EXISTS roles (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS permissions (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS user_roles (user_id CHAR(36) NOT NULL, role_id SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS role_permissions (role_id SMALLINT UNSIGNED NOT NULL, permission_id SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS otp_challenges (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, purpose ENUM('VERIFY_EMAIL','LOGIN','RESET_PASSWORD') NOT NULL, code_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, consumed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_otp_lookup(user_id,purpose,expires_at));
CREATE TABLE IF NOT EXISTS refresh_sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_sessions_user(user_id,revoked_at));
CREATE TABLE IF NOT EXISTS events (id CHAR(36) PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, description TEXT NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, venue VARCHAR(255) NOT NULL, status ENUM('DRAFT','PENDING_APPROVAL','APPROVED','PUBLISHED','REJECTED') NOT NULL DEFAULT 'DRAFT', created_by CHAR(36) NOT NULL, approved_by CHAR(36) NULL, published_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id), INDEX idx_events_status(status,starts_at));
CREATE TABLE IF NOT EXISTS event_media (id CHAR(36) PRIMARY KEY, event_id CHAR(36) NOT NULL, url VARCHAR(1024) NOT NULL, alt_text VARCHAR(255) NOT NULL, sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS visitor_profiles (id CHAR(36) PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, full_name VARCHAR(160) NOT NULL, email_verified_at DATETIME NULL, marketing_consent BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_registrations (id CHAR(36) PRIMARY KEY, event_id CHAR(36) NOT NULL, visitor_id CHAR(36) NOT NULL, status ENUM('REGISTERED','CANCELLED') NOT NULL DEFAULT 'REGISTERED', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_registration(event_id,visitor_id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(visitor_id) REFERENCES visitor_profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS qr_passes (id CHAR(36) PRIMARY KEY, registration_id CHAR(36) NOT NULL UNIQUE, token_hash CHAR(64) NOT NULL UNIQUE, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(registration_id) REFERENCES event_registrations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS check_ins (id CHAR(36) PRIMARY KEY, pass_id CHAR(36) NOT NULL UNIQUE, checked_in_by CHAR(36) NOT NULL, checked_in_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(pass_id) REFERENCES qr_passes(id), FOREIGN KEY(checked_in_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS artist_applications (id CHAR(36) PRIMARY KEY, applicant_name VARCHAR(160) NOT NULL, email VARCHAR(255) NOT NULL, portfolio_url VARCHAR(1024) NOT NULL, statement TEXT NOT NULL, status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', reviewed_by CHAR(36) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_enquiries (id CHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(255) NOT NULL, message TEXT NOT NULL, status ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id CHAR(36) NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id CHAR(36) NULL, metadata JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_audit_created(created_at));
CREATE TABLE IF NOT EXISTS email_notification_preferences (visitor_id CHAR(36) PRIMARY KEY, announcements BOOLEAN NOT NULL DEFAULT FALSE, transactional BOOLEAN NOT NULL DEFAULT TRUE, unsubscribe_token_hash CHAR(64) NULL UNIQUE, FOREIGN KEY(visitor_id) REFERENCES visitor_profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS email_delivery_records (id CHAR(36) PRIMARY KEY, recipient_email VARCHAR(255) NOT NULL, template VARCHAR(100) NOT NULL, status ENUM('QUEUED','SENT','FAILED') NOT NULL DEFAULT 'QUEUED', attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, last_error TEXT NULL, sent_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_email_status(status,created_at));

INSERT IGNORE INTO roles(name) VALUES ('SUPER_ADMIN'),('ADMIN'),('CONTENT_MANAGER'),('VISITOR'),('ARTIST_EXHIBITOR');
INSERT IGNORE INTO permissions(name) VALUES ('events:read'),('events:create'),('events:edit'),('events:approve'),('events:publish'),('visitors:read'),('passes:scan'),('users:manage'),('audit:read');
